import { useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  Activity, AlertTriangle, ArrowLeft, ArrowUpRight, BarChart3, BookOpen, BrainCircuit,
  Check, ChevronRight, CircleCheck, ClipboardList, Clock3, Crosshair, Database,
  ExternalLink, Fan, FileSpreadsheet, Filter, Gauge, Info, Layers3, Lightbulb, Menu,
  Network, RefreshCw, Search, Send, ServerCog, Settings2, ShieldAlert, SlidersHorizontal,
  Sparkles, Thermometer, TriangleAlert, UploadCloud, Wrench, X,
} from 'lucide-react';
import {
  getGetAnalysisSummaryQueryKey, getGetDashboardSummaryQueryKey, getGetMachineQueryKey, getGetMachinesQueryKey,
  getGetModelResultsQueryKey, getGetPredictionsQueryKey, getGetRagSourcesQueryKey,
  useCreatePrediction, useGetAnalysisSummary, useGetDashboardSummary, useGetMachine,
  useGetMachines, useGetModelResults, useGetPredictions, useGetRagSources,
  useLoadDemoDataset, useProfileDataset, useQueryMaintenanceKnowledge, useTrainModels,
  useUploadDataset,
  type AnalysisSummary, type DatasetProfile, type DashboardSummary, type Machine, type MachineDetail,
  type ModelResult, type Prediction, type RagResponse, type RagSource, type TrainingResults,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();

const navItems = [
  { href: '/', label: 'Overview', icon: Gauge },
  { href: '/dataset', label: 'Dataset profile', icon: Database },
  { href: '/analysis', label: 'Analysis', icon: BarChart3 },
  { href: '/predict', label: 'Run prediction', icon: Crosshair },
  { href: '/predictions', label: 'Prediction history', icon: ClipboardList },
  { href: '/machines', label: 'Machines', icon: ServerCog },
  { href: '/insights', label: 'Maintenance knowledge', icon: BookOpen },
  { href: '/models', label: 'Model registry', icon: BrainCircuit },
];

const cx = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(' ');
const formatDate = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const formatPct = (value?: number | null) => value == null ? '—' : `${(value * 100).toFixed(1)}%`;
const cap = (value?: string | null) => value ? value.charAt(0).toUpperCase() + value.slice(1).toLowerCase() : 'Unknown';

function StatusBadge({ value, subtle = false }: { value?: string | null; subtle?: boolean }) {
  const normalized = value?.toLowerCase() ?? 'unknown';
  const isGood = ['healthy', 'normal', 'low'].includes(normalized);
  const isBad = ['critical', 'high', 'failure'].includes(normalized);
  return <span data-testid={`status-${normalized}`} className={cx('inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold tracking-wide', isGood ? 'bg-emerald-50 text-emerald-700' : isBad ? 'bg-red-50 text-[#ab2c26]' : 'bg-amber-50 text-amber-700', subtle && 'border border-current/15')}>
    <span className={cx('h-1.5 w-1.5 rounded-full', isGood ? 'bg-emerald-500' : isBad ? 'bg-[#c43a32]' : 'bg-amber-500')} />{cap(value)}
  </span>;
}

function Panel({ children, className, title, eyebrow, action }: { children: React.ReactNode; className?: string; title?: string; eyebrow?: string; action?: React.ReactNode }) {
  return <section className={cx('rounded-2xl border border-[#e4ddd3] bg-[#fffdfa] shadow-sm', className)}>
    {(title || eyebrow || action) && <div className="flex items-start justify-between gap-3 border-b border-[#eee7df] px-5 py-4">
      <div>{eyebrow && <div className="mono-label text-[#a44b42]">{eyebrow}</div>}{title && <h2 className="mt-1 text-[15px] font-extrabold tracking-[-.02em] text-[#1f2631]">{title}</h2>}</div>
      {action}
    </div>}
    {children}
  </section>;
}

function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('animate-pulse rounded-lg bg-[#eee7df]', className)} />; }
function QueryState({ loading, error, onRetry, children }: { loading?: boolean; error?: boolean; onRetry?: () => void; children: React.ReactNode }) {
  if (loading) return <div className="space-y-3"><Skeleton className="h-24 w-full" /><Skeleton className="h-40 w-full" /></div>;
  if (error) return <div className="rounded-2xl border border-red-200 bg-red-50/60 p-6 text-center"><TriangleAlert className="mx-auto mb-2 h-5 w-5 text-[#b33a31]" /><p className="text-sm font-semibold text-[#8c2c25]">We could not retrieve this workspace view.</p><button data-testid="button-retry" onClick={onRetry} className="mt-3 inline-flex items-center gap-2 rounded-lg bg-[#b3342c] px-3 py-2 text-xs font-bold text-white hover:bg-[#922922]"><RefreshCw className="h-3.5 w-3.5" /> Retry</button></div>;
  return <>{children}</>;
}

function MechanicalMark({ small = false }: { small?: boolean }) {
  return <div className={cx('relative grid place-items-center rounded-xl bg-[#b3342c] text-white shadow-[0_5px_16px_rgba(179,52,44,.2)]', small ? 'h-8 w-8 rounded-lg' : 'h-14 w-14')} aria-label="Predictive Maintenance mark">
    <Settings2 className={cx('absolute', small ? 'h-4 w-4' : 'h-7 w-7')} strokeWidth={1.5} />
    <span className={cx('absolute rounded-full border border-white/70', small ? 'h-2 w-2' : 'h-4 w-4')} />
    <span className="absolute -right-1 top-1/2 h-1 w-2 rounded-full bg-[#f6c7bd]" />
  </div>;
}

function Shell({ children }: { children: React.ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const current = navItems.find((item) => item.href === location)?.label ?? (location.startsWith('/machines/') ? 'Machines' : 'Overview');
  return <div className="min-h-[100dvh] bg-[#f5f1eb] text-[#1f2631]">
    <aside className={cx('fixed inset-y-0 left-0 z-40 w-[252px] bg-[#20242c] text-white transition-transform duration-300 md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex h-full flex-col">
        <div className="flex items-center gap-3 border-b border-white/10 px-5 py-5"><MechanicalMark small /><div><div className="text-sm font-extrabold tracking-tight">Predictive</div><div className="mono-label text-white/45">Maintenance / OS</div></div><button data-testid="button-close-menu" onClick={() => setMobileOpen(false)} className="ml-auto rounded-lg p-1 text-white/60 hover:bg-white/10 md:hidden"><X className="h-4 w-4" /></button></div>
        <div className="px-5 pt-6"><div className="mono-label mb-3 text-white/35">Workspace</div><nav className="space-y-1">
          {navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileOpen(false)} className={cx('flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold transition-colors', location === href ? 'bg-[#b3342c] text-white shadow-lg shadow-red-950/20' : 'text-white/58 hover:bg-white/8 hover:text-white')}><Icon className="h-[17px] w-[17px]" strokeWidth={1.8} /><span>{label}</span>{location === href && <ChevronRight className="ml-auto h-3.5 w-3.5" />}</Link>)}
        </nav></div>
        <div className="mt-auto p-5"><div className="rounded-xl border border-white/10 bg-white/[.04] p-3.5"><div className="flex items-center gap-2 text-[11px] font-bold text-white/75"><span className="signal-pulse h-2 w-2 rounded-full bg-emerald-400" /> System connected</div><p className="mt-2 text-[11px] leading-relaxed text-white/40">Evidence layer online. Dataset, model, and knowledge sources are traceable.</p></div><div className="mono-label mt-5 text-white/25">PRED-OPS 0.8.4</div></div>
      </div>
    </aside>
    {mobileOpen && <button data-testid="button-mobile-overlay" aria-label="Close navigation" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-[#171a20]/55 md:hidden" />}
    <main className="min-w-0 md:pl-[252px]">
      <header className="sticky top-0 z-20 flex h-[70px] items-center justify-between border-b border-[#e4ddd3] bg-[#f5f1eb]/90 px-4 backdrop-blur md:px-8">
        <div className="flex items-center gap-3"><button data-testid="button-open-menu" onClick={() => setMobileOpen(true)} className="rounded-lg p-2 hover:bg-[#e9e1d8] md:hidden"><Menu className="h-5 w-5" /></button><div><div className="mono-label text-[#9c9185]">Operations / {current}</div><h1 className="mt-0.5 text-sm font-extrabold text-[#222832]">{current}</h1></div></div>
        <div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-lg border border-[#ded5ca] bg-[#fffdfa] px-3 py-2 text-xs text-[#8d847b] sm:flex"><Search className="h-3.5 w-3.5" /> Search workspace <kbd className="ml-3 rounded bg-[#f2ece5] px-1.5 py-0.5 font-mono text-[10px]">⌘K</kbd></div><div className="grid h-8 w-8 place-items-center rounded-full bg-[#ede3d9] text-xs font-bold text-[#9a433a]">OE</div></div>
      </header>
      <div className="mx-auto max-w-[1500px] p-4 md:p-8">{children}</div>
    </main>
  </div>;
}

function PageIntro({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><div className="mono-label text-[#b3342c]">{eyebrow}</div><h1 className="mt-2 max-w-3xl text-3xl font-extrabold tracking-[-.045em] text-[#1e252f] md:text-[38px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#706b66]">{description}</p></div>{children && <div className="flex shrink-0 gap-2">{children}</div>}</div>;
}

function Metric({ label, value, detail, icon: Icon, tone = 'neutral' }: { label: string; value: string | number; detail: string; icon: React.ElementType; tone?: 'neutral' | 'red' | 'green' | 'amber' }) {
  return <div data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="rounded-2xl border border-[#e4ddd3] bg-[#fffdfa] p-4 shadow-sm"><div className="flex items-start justify-between"><div className="mono-label text-[#9b9287]">{label}</div><div className={cx('grid h-8 w-8 place-items-center rounded-lg', tone === 'red' ? 'bg-red-50 text-[#b3342c]' : tone === 'green' ? 'bg-emerald-50 text-emerald-600' : tone === 'amber' ? 'bg-amber-50 text-amber-600' : 'bg-[#f0ebe5] text-[#80776d]')}><Icon className="h-4 w-4" /></div></div><div className="mt-5 text-2xl font-extrabold tracking-[-.04em] text-[#222832]">{value}</div><div className="mt-1 text-[11px] text-[#898076]">{detail}</div></div>;
}

function EmptyState({ icon: Icon, title, body, action }: { icon: React.ElementType; title: string; body: string; action?: React.ReactNode }) {
  return <div className="grid min-h-[210px] place-items-center p-8 text-center"><div><div className="mx-auto grid h-11 w-11 place-items-center rounded-xl bg-[#f1e8e1] text-[#b3342c]"><Icon className="h-5 w-5" /></div><h3 className="mt-3 text-sm font-extrabold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-xs leading-5 text-[#80776d]">{body}</p>{action && <div className="mt-4">{action}</div>}</div></div>;
}

function Overview() {
  const summary = useGetDashboardSummary();
  const analysis = useGetAnalysisSummary();
  const machines = useGetMachines();
  const sources = useGetRagSources({ query: { queryKey: getGetRagSourcesQueryKey() } });
  const loadDemo = useLoadDemoDataset();
  const qc = useQueryClient();
  const data = summary.data;
  const classData = analysis.data?.distribution ?? [];
  const machineRows = machines.data ?? [];
  const refresh = () => { summary.refetch(); analysis.refetch(); machines.refetch(); };
  return <div className="rise-in">
    <div className="hero-geometry relative overflow-hidden rounded-3xl border border-[#e8d9d0] bg-[#fbf1ec] p-6 md:p-9"><div className="relative z-10 grid gap-7 lg:grid-cols-[minmax(0,1fr)_240px] lg:items-end"><div className="max-w-3xl"><div className="mono-label flex items-center gap-2 text-[#a94a40]"><span className="h-1.5 w-1.5 rounded-full bg-[#b3342c]" /> Predictive maintenance command center</div><h1 className="mt-4 max-w-2xl text-4xl font-extrabold leading-[1.02] tracking-[-.06em] text-[#202630] md:text-[54px]">Know what is changing<br /><span className="text-[#b3342c]">before it becomes a stop.</span></h1><p className="mt-5 max-w-xl text-sm leading-6 text-[#625b56]">A dataset-agnostic workspace for reading machine health with evidence in view: the selected model, the signal behind it, and the maintenance knowledge that supports the call.</p><div className="mt-7 flex flex-wrap gap-3"><Link href="/predict" data-testid="link-hero-predict" className="inline-flex items-center gap-2 rounded-xl bg-[#b3342c] px-4 py-3 text-xs font-extrabold text-white shadow-lg shadow-red-900/15 transition-transform hover:-translate-y-0.5">Run a prediction <ArrowUpRight className="h-4 w-4" /></Link><button data-testid="button-load-demo" disabled={loadDemo.isPending} onClick={() => loadDemo.mutate(undefined, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); qc.invalidateQueries({ queryKey: getGetAnalysisSummaryQueryKey() }); } })} className="inline-flex items-center gap-2 rounded-xl border border-[#d6bbb1] bg-[#fffdfa]/70 px-4 py-3 text-xs font-extrabold text-[#87332c] hover:bg-white disabled:opacity-60">{loadDemo.isPending ? 'Loading demo…' : 'Load demo fleet'} <Database className="h-4 w-4" /></button></div></div><div className="hidden rounded-2xl border border-[#d6bbb1] bg-[#fffdfa]/80 p-4 shadow-sm backdrop-blur md:block lg:mb-1"><div className="mono-label text-[#a69488]">Signal posture</div><div className="mt-2 flex items-center gap-2 text-xl font-extrabold"><span className="h-2.5 w-2.5 rounded-full bg-emerald-500" /> {data ? `${Math.round((data.healthy / Math.max(data.machines, 1)) * 100)}% stable` : 'Awaiting data'}</div><div className="mt-1 text-[11px] text-[#877c73]">based on latest machine readings</div></div></div><div className="absolute -right-8 -top-10 hidden h-64 w-64 rounded-full border-[20px] border-[#b3342c]/10 md:block" /></div>
    <QueryState loading={summary.isLoading || analysis.isLoading} error={summary.isError || analysis.isError} onRetry={refresh}><div className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Machines" value={data?.machines ?? '—'} detail={`${data?.healthy ?? 0} currently healthy`} icon={ServerCog} tone="neutral" /><Metric label="At risk" value={data?.atRisk ?? '—'} detail={`${data?.critical ?? 0} need attention`} icon={AlertTriangle} tone="amber" /><Metric label="Predictions" value={data?.totalPredictions ?? '—'} detail="recorded in workspace" icon={Crosshair} tone="red" /><Metric label="Missing values" value={data?.missingValues ?? '—'} detail={data?.dataset ? `in ${data.dataset}` : 'dataset signal'} icon={Layers3} tone={data?.missingValues ? 'amber' : 'green'} /></div></QueryState>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Panel eyebrow="Current posture" title="Health distribution" action={<Link href="/analysis" data-testid="link-overview-analysis" className="text-xs font-bold text-[#b3342c]">Open analysis <ChevronRight className="ml-1 inline h-3.5 w-3.5" /></Link>}><div className="p-5">{classData.length ? <div className="space-y-4">{classData.map((item) => <div key={item.label} data-testid={`distribution-${item.label}`}><div className="mb-1.5 flex justify-between text-xs font-bold"><span>{cap(item.label)}</span><span className="font-mono text-[#837a71]">{item.count} · {item.percentage.toFixed(1)}%</span></div><div className="h-2 overflow-hidden rounded-full bg-[#eee8e1]"><div className={cx('h-full rounded-full', item.label.toLowerCase().includes('critical') ? 'bg-[#b3342c]' : item.label.toLowerCase().includes('risk') ? 'bg-[#d99b3d]' : 'bg-[#469778]')} style={{ width: `${item.percentage}%` }} /></div></div>)}</div> : <EmptyState icon={BarChart3} title="No distribution yet" body="Load a demo dataset or upload a profile to see health posture." />}</div></Panel><Panel eyebrow="Evidence layer" title="Latest knowledge sources"><div className="divide-y divide-[#eee7df]">{sources.data?.slice(0, 3).map((source) => <div key={source.id} className="p-4"><div className="flex items-start gap-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#f2e6e0] text-[#b3342c]"><BookOpen className="h-4 w-4" /></div><div><div className="text-xs font-extrabold">{source.title}</div><div className="mono-label mt-1 text-[#a59a8f]">{source.category}</div><p className="mt-2 line-clamp-2 text-[11px] leading-5 text-[#79716a]">{source.excerpt}</p></div></div></div>) ?? <EmptyState icon={BookOpen} title="Knowledge index is empty" body="Retrieved maintenance sources will appear here after the knowledge layer is connected." />}</div><div className="border-t border-[#eee7df] p-4"><Link href="/insights" data-testid="link-overview-insights" className="text-xs font-bold text-[#b3342c]">Explore grounded insights <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></Link></div></Panel></div>
    <Panel className="mt-6" eyebrow="Fleet register" title="Machines needing a closer look" action={<Link href="/machines" data-testid="link-overview-machines" className="text-xs font-bold text-[#b3342c]">View all <ChevronRight className="ml-1 inline h-3.5 w-3.5" /></Link>}><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left"><thead className="bg-[#faf6f1] text-[10px] uppercase tracking-[.12em] text-[#9d9287]"><tr><th className="px-5 py-3 font-bold">Machine</th><th className="px-5 py-3 font-bold">Health</th><th className="px-5 py-3 font-bold">Risk</th><th className="px-5 py-3 font-bold">Last seen</th><th /></tr></thead><tbody className="divide-y divide-[#eee7df]">{machineRows.slice(0, 5).map((machine) => <tr key={machine.id} className="text-xs hover:bg-[#fcf8f4]"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-[#eee9e3] text-[#706960]"><Fan className="h-4 w-4" /></div><div><div className="font-extrabold">{machine.id}</div><div className="text-[11px] text-[#8c8379]">{machine.type}</div></div></div></td><td className="px-5 py-3.5"><StatusBadge value={machine.health} /></td><td className="px-5 py-3.5"><StatusBadge value={machine.risk} subtle /></td><td className="px-5 py-3.5 text-[#80776e]">{formatDate(machine.lastSeen)}</td><td className="px-5 py-3.5 text-right"><Link href={`/machines/${machine.id}`} data-testid={`link-machine-${machine.id}`} className="text-[#b3342c]"><ChevronRight className="h-4 w-4" /></Link></td></tr>)}</tbody></table>{!machineRows.length && <EmptyState icon={ServerCog} title="No machine records" body="Machine records will appear when a dataset has been profiled." />}</div></Panel>
  </div>;
}

function DatasetPage() {
  const summary = useGetDashboardSummary();
  const loadDemo = useLoadDemoDataset();
  const upload = useUploadDataset();
  const profile = useProfileDataset();
  const qc = useQueryClient();
  const [target, setTarget] = useState('');
  const [jsonText, setJsonText] = useState('');
  const [uploadName, setUploadName] = useState('uploaded-dataset');
  const [profileData, setProfileData] = useState<DatasetProfile | undefined>();
  const datasetId = profileData?.id ?? (summary.data?.dataset || '');
  const onFile = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]; if (!file) return; setUploadName(file.name.replace(/\.[^.]+$/, '')); const reader = new FileReader(); reader.onload = () => setJsonText(String(reader.result ?? '')); reader.readAsText(file);
  };
  const parseAndUpload = () => { try { const parsed = JSON.parse(jsonText); const rows = Array.isArray(parsed) ? parsed : parsed.rows; const columns = Object.keys(rows?.[0] ?? {}); upload.mutate({ data: { name: uploadName, columns, rows, targetColumn: target || null } }, { onSuccess: (data) => { setProfileData(data); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); } }); } catch { setJsonText('Invalid JSON — provide an array of row objects.'); } };
  const applyTarget = () => { if (datasetId && target) profile.mutate({ data: { datasetId, targetColumn: target } }, { onSuccess: (data) => setProfileData(data) }); };
  const data = profileData;
  return <div className="rise-in"><PageIntro eyebrow="Data foundation" title="Dataset profile" description="Inspect the shape of the evidence before asking the model to make a maintenance call." ><button data-testid="button-dataset-demo" onClick={() => loadDemo.mutate(undefined, { onSuccess: (d) => { setProfileData(d); setTarget(d.targetColumn ?? d.possibleTargets[0] ?? ''); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); } })} className="inline-flex items-center gap-2 rounded-xl bg-[#b3342c] px-4 py-3 text-xs font-extrabold text-white disabled:opacity-60">{loadDemo.isPending ? 'Loading…' : 'Use demo dataset'} <Sparkles className="h-4 w-4" /></button></PageIntro>
    <div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Panel eyebrow="01 / Ingest" title="Upload structured data"><div className="p-5"><label data-testid="label-upload-file" className="group flex cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed border-[#d8c9bc] bg-[#fcf8f4] px-6 py-9 text-center hover:border-[#b3342c]"><input data-testid="input-upload-file" type="file" accept=".json,.csv" onChange={onFile} className="sr-only" /><UploadCloud className="h-7 w-7 text-[#b3342c]" /><span className="mt-3 text-sm font-extrabold">Choose a CSV or JSON file</span><span className="mt-1 text-xs text-[#8b8178]">The client parses rows, columns, and target candidates.</span></label><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs font-bold text-[#645d56]">Dataset name<input data-testid="input-dataset-name" value={uploadName} onChange={(e) => setUploadName(e.target.value)} className="mt-1.5 w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#b3342c]" /></label><label className="text-xs font-bold text-[#645d56]">Target hint <input data-testid="input-target-hint" value={target} onChange={(e) => setTarget(e.target.value)} placeholder="optional" className="mt-1.5 w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#b3342c]" /></label></div><label className="mt-4 block text-xs font-bold text-[#645d56]">Or paste JSON rows<textarea data-testid="input-json-rows" value={jsonText} onChange={(e) => setJsonText(e.target.value)} rows={5} placeholder='[{"temperature": 72, "vibration": 0.18, "health": "healthy"}]' className="mt-1.5 w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 font-mono text-[11px] outline-none focus:border-[#b3342c]" /></label><button data-testid="button-upload-dataset" onClick={parseAndUpload} disabled={upload.isPending || !jsonText} className="mt-4 inline-flex items-center gap-2 rounded-lg bg-[#20242c] px-4 py-2.5 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-45">{upload.isPending ? 'Profiling…' : 'Upload and profile'} <ArrowUpRight className="h-3.5 w-3.5" /></button>{upload.isError && <p className="mt-3 text-xs font-semibold text-[#a32d27]">Upload failed. Check the row structure and retry.</p>}</div></Panel><Panel eyebrow="02 / Readiness" title="Profile signal"><div className="p-5"><QueryState loading={summary.isLoading} error={summary.isError} onRetry={() => summary.refetch()}>{data || summary.data ? <><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Rows" value={data?.rows ?? summary.data?.rows ?? '—'} detail="observations" icon={FileSpreadsheet} /><Metric label="Features" value={data?.columns ?? summary.data?.features ?? '—'} detail="candidate inputs" icon={SlidersHorizontal} /><Metric label="Missing" value={data?.missingValues ?? summary.data?.missingValues ?? '—'} detail="values to review" icon={TriangleAlert} tone={data?.missingValues ? 'amber' : 'green'} /><Metric label="Duplicates" value={data?.duplicateRows ?? '—'} detail="repeated rows" icon={Layers3} /></div><div className="mt-6 rounded-xl border border-[#eee7df] p-4"><div className="flex items-center justify-between"><div><div className="text-xs font-extrabold">Select prediction target</div><p className="mt-1 text-[11px] text-[#847b72]">Re-profile the dataset after changing the target.</p></div><button data-testid="button-profile-dataset" onClick={applyTarget} disabled={profile.isPending || !target || !datasetId} className="rounded-lg border border-[#d9c8bf] px-3 py-2 text-[11px] font-bold text-[#8f322c] disabled:opacity-40">{profile.isPending ? 'Applying…' : 'Apply target'}</button></div><select data-testid="select-target-column" value={target || data?.targetColumn || ''} onChange={(e) => setTarget(e.target.value)} className="mt-4 w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#b3342c]"><option value="">Choose a target column</option>{(data?.possibleTargets ?? [summary.data?.target].filter(Boolean) as string[]).map((item) => <option key={item} value={item}>{item}</option>)}</select></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><div><div className="mono-label text-[#a1968b]">Numerical features</div><div className="mt-2 flex flex-wrap gap-1.5">{(data?.numericalFeatures ?? []).map((item) => <span key={item} className="rounded-md bg-[#f0ebe5] px-2 py-1 font-mono text-[10px] text-[#665e56]">{item}</span>)}</div></div><div><div className="mono-label text-[#a1968b]">Categorical features</div><div className="mt-2 flex flex-wrap gap-1.5">{(data?.categoricalFeatures ?? []).map((item) => <span key={item} className="rounded-md bg-[#f9e8e3] px-2 py-1 font-mono text-[10px] text-[#994039]">{item}</span>)}</div></div></div></> : <EmptyState icon={Database} title="No profile loaded" body="Use the built-in demo or upload a structured dataset to inspect readiness." />}</QueryState></div></Panel></div>
    <Panel className="mt-6" eyebrow="Class balance" title="Target distribution"><div className="p-5">{data?.classDistribution?.length ? <div className="grid gap-3 sm:grid-cols-3">{data.classDistribution.map((item) => <div key={item.label} className="rounded-xl bg-[#faf6f1] p-4"><div className="flex items-center justify-between"><span className="text-xs font-bold">{cap(item.label)}</span><span className="font-mono text-xs text-[#8b8178]">{item.count}</span></div><div className="mt-3 h-1.5 rounded-full bg-[#e8ded5]"><div className="h-full rounded-full bg-[#b3342c]" style={{ width: `${item.percentage}%` }} /></div><div className="mt-2 text-[11px] text-[#8d8379]">{item.percentage.toFixed(1)}% of rows</div></div>)}</div> : <EmptyState icon={BarChart3} title="Target classes not profiled" body="Choose a target column to see class balance." />}</div></Panel>
  </div>;
}

function AnalysisPage() {
  const analysis = useGetAnalysisSummary();
  const results = useGetModelResults({ query: { queryKey: getGetModelResultsQueryKey() } });
  const train = useTrainModels();
  const dashboard = useGetDashboardSummary();
  const [target, setTarget] = useState('');
  const data = analysis.data;
  const modelData = results.data?.models ?? data?.modelResults ?? [];
  const startTraining = () => { const targetColumn = target || dashboard.data?.target; if (dashboard.data?.dataset && targetColumn) train.mutate({ data: { datasetId: dashboard.data.dataset, targetColumn } }); };
  return <div className="rise-in"><PageIntro eyebrow="Model evidence" title="Analysis" description="Read the health distribution, benchmark alternatives, and inspect which signals carry the model's decision."><div className="flex gap-2"><input data-testid="input-analysis-target" value={target} onChange={(e) => setTarget(e.target.value)} placeholder={dashboard.data?.target ?? 'target column'} className="w-36 rounded-xl border border-[#d9cfc5] bg-[#fffdfa] px-3 py-3 text-xs outline-none focus:border-[#b3342c]" /><button data-testid="button-train-models" onClick={startTraining} disabled={train.isPending || !dashboard.data?.dataset} className="inline-flex items-center gap-2 rounded-xl bg-[#b3342c] px-4 py-3 text-xs font-extrabold text-white disabled:opacity-50">{train.isPending ? 'Training…' : 'Train & compare'} <BrainCircuit className="h-4 w-4" /></button></div></PageIntro><QueryState loading={analysis.isLoading || results.isLoading} error={analysis.isError && results.isError} onRetry={() => { analysis.refetch(); results.refetch(); }}><div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Panel eyebrow="01 / Distribution" title="Health labels"><div className="p-5">{data?.distribution?.length ? <div className="space-y-4">{data.distribution.map((item) => <div key={item.label} className="flex items-center gap-3"><div className="w-20 text-xs font-bold">{cap(item.label)}</div><div className="h-3 flex-1 rounded-full bg-[#eee8e1]"><div className="h-full rounded-full bg-[#b3342c]" style={{ width: `${item.percentage}%` }} /></div><div className="w-16 text-right font-mono text-xs text-[#81786f]">{item.count} / {item.percentage.toFixed(1)}%</div></div>)}</div> : <EmptyState icon={BarChart3} title="No class distribution" body="Profile a dataset before analysing its target." />}</div></Panel><Panel eyebrow="02 / Benchmark" title="Model comparison" action={<span className="mono-label text-[#9d9287]">{modelData.length} candidates</span>}><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-xs"><thead className="bg-[#faf6f1] text-[10px] uppercase tracking-[.1em] text-[#9d9287]"><tr><th className="px-5 py-3">Model</th><th className="px-3 py-3">Accuracy</th><th className="px-3 py-3">Precision</th><th className="px-3 py-3">Recall</th><th className="px-3 py-3">F1</th><th className="px-3 py-3" /></tr></thead><tbody className="divide-y divide-[#eee7df]">{modelData.map((model) => <tr key={model.name} className={cx('hover:bg-[#fcf8f4]', model.selected && 'bg-[#fff4f0]')}><td className="px-5 py-4"><div className="font-extrabold">{model.name}</div><div className="mt-1 text-[10px] text-[#8d8379]">{model.note}</div></td><td className="px-3 py-4 font-mono">{formatPct(model.accuracy)}</td><td className="px-3 py-4 font-mono">{formatPct(model.precision)}</td><td className="px-3 py-4 font-mono">{formatPct(model.recall)}</td><td className="px-3 py-4 font-mono font-bold">{formatPct(model.f1)}</td><td className="px-3 py-4">{model.selected && <span className="rounded-full bg-[#b3342c] px-2 py-1 text-[10px] font-bold text-white">Selected</span>}</td></tr>)}</tbody></table>{!modelData.length && <EmptyState icon={BrainCircuit} title="No trained models" body="Train the first comparison set after selecting a target." />}</div></Panel></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Panel eyebrow="03 / Error map" title="Confusion matrix"><div className="p-5">{results.data?.confusionMatrix?.length ? <div className="overflow-x-auto"><div className="grid min-w-[330px] grid-cols-[110px_repeat(3,1fr)] gap-1 text-center text-xs">{[null, ...(results.data.confusionLabels ?? [])].map((label, i) => <div key={`h-${i}`} className="p-2 font-mono text-[10px] text-[#90867c]">{label ? `Pred ${label}` : ''}</div>)}{results.data.confusionMatrix.map((row, i) => <><div key={`r-${i}`} className="p-3 text-left font-mono text-[10px] text-[#90867c]">Actual {results.data?.confusionLabels?.[i]}</div>{row.map((value, j) => <div key={`${i}-${j}`} className={cx('grid min-h-14 place-items-center rounded-lg font-mono text-sm font-bold', i === j ? 'bg-[#dceee6] text-[#26694e]' : 'bg-[#f8e1dc] text-[#a3372e]')} style={{ opacity: .55 + Math.min(value / 10, .45) }}>{value}</div>)}</>)}</div></div> : <EmptyState icon={Crosshair} title="Confusion matrix unavailable" body="The selected model will expose errors after training." />}</div></Panel><Panel eyebrow="04 / Signal attribution" title="Feature importance"><div className="p-5">{(results.data?.featureImportance ?? data?.topFeatures ?? []).length ? <div className="space-y-3">{(results.data?.featureImportance ?? data?.topFeatures ?? []).slice(0, 8).map((item) => <div key={item.feature}><div className="mb-1 flex justify-between text-xs"><span className="font-bold">{item.feature}</span><span className="font-mono text-[#8b8178]">{item.importance.toFixed(3)}</span></div><div className="h-2 rounded-full bg-[#eee8e1]"><div className="h-full rounded-full bg-[#b3342c]" style={{ width: `${Math.min(item.importance * 100, 100)}%` }} /></div></div>)}</div> : <EmptyState icon={SlidersHorizontal} title="No feature ranking" body="Train a model to surface the signals that matter most." />}</div></Panel></div></QueryState></div>;
}

function PredictPage() {
  const summary = useGetDashboardSummary();
  const prediction = useCreatePrediction();
  const models = useGetModelResults();
  const history = useGetPredictions();
  const [machineId, setMachineId] = useState('');
  const [values, setValues] = useState<Record<string, string>>({ temperature: '72', vibration: '0.18', pressure: '101.4', rpm: '1480' });
  const datasetId = summary.data?.dataset || 'demo-fleet';
  const fields = ['temperature', 'vibration', 'pressure', 'rpm'];
  const submit = (event: React.FormEvent) => { event.preventDefault(); const parsed = Object.fromEntries(Object.entries(values).map(([key, value]) => [key, value === '' ? null : Number(value)])); prediction.mutate({ data: { datasetId, machineId: machineId || null, values: parsed } }); };
  return <div className="rise-in"><PageIntro eyebrow="Inference console" title="Run a prediction" description="A manual sensor reading stays traceable: the ML result is shown alongside its indicators and the maintenance explanation that follows."><div className="rounded-xl border border-[#d8c7bf] bg-[#fffdfa] px-3 py-2.5 text-right"><div className="mono-label text-[#9a8e84]">Selected model</div><div className="mt-1 text-xs font-extrabold">{models.data?.selectedModel ?? 'Model pending'}</div></div></PageIntro><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><Panel eyebrow="Sensor input" title="Manual reading"><form onSubmit={submit} className="p-5"><label className="block text-xs font-bold">Machine reference<input data-testid="input-predict-machine" value={machineId} onChange={(e) => setMachineId(e.target.value)} placeholder="optional, e.g. pump-07" className="mt-1.5 w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#b3342c]" /></label><div className="mt-5 grid grid-cols-2 gap-3">{fields.map((field) => <label key={field} className="text-xs font-bold capitalize">{field}<div className="relative mt-1.5"><input data-testid={`input-sensor-${field}`} type="number" step="any" value={values[field] ?? ''} onChange={(e) => setValues((current) => ({ ...current, [field]: e.target.value }))} className="w-full rounded-lg border border-[#ded4ca] bg-white px-3 py-2.5 pr-14 font-mono text-sm outline-none focus:border-[#b3342c]" /><span className="absolute right-3 top-2.5 font-mono text-[10px] text-[#9a9188]">{field === 'temperature' ? '°C' : field === 'rpm' ? 'rpm' : 'unit'}</span></div></label>)}</div><button data-testid="button-create-prediction" type="submit" disabled={prediction.isPending} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#b3342c] py-3 text-xs font-extrabold text-white shadow-lg shadow-red-900/10 disabled:opacity-55">{prediction.isPending ? 'Evaluating reading…' : 'Evaluate machine health'} <Crosshair className="h-4 w-4" /></button>{prediction.isError && <div className="mt-3 rounded-lg bg-red-50 p-3 text-xs font-semibold text-[#9b3029]">Prediction could not be created. Confirm a profiled dataset is ready.</div>}</form></Panel><Panel eyebrow="Result" title="Evidence stack"><div className="p-5">{prediction.data ? <PredictionResult prediction={prediction.data} /> : <EmptyState icon={Crosshair} title="No reading evaluated" body="Enter sensor values to see the ML classification and its supporting evidence." />}</div></Panel></div><Panel className="mt-6" eyebrow="Recent context" title="Last three predictions"><div className="divide-y divide-[#eee7df]">{(history.data ?? []).slice(0, 3).map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><div className="text-xs font-extrabold">{item.machineId || 'Unassigned reading'}</div><div className="mt-1 text-[11px] text-[#8d8379]">{formatDate(item.createdAt)} · {item.model}</div></div><div className="flex items-center gap-3"><StatusBadge value={item.health} /><span className="font-mono text-xs text-[#7f766d]">{formatPct(item.confidence)}</span></div></div>)}{!history.data?.length && <EmptyState icon={ClipboardList} title="No prediction history" body="Your evaluated readings will be retained here." />}</div></Panel></div>;
}

function PredictionResult({ prediction }: { prediction: Prediction }) {
  return <div><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-[#faf1ed] p-4"><div><div className="mono-label text-[#a44c43]">ML prediction</div><div className="mt-1 text-2xl font-extrabold tracking-[-.04em]">{cap(prediction.health)}</div></div><div className="text-right"><div className="mono-label text-[#a69a90]">Confidence</div><div className="mt-1 font-mono text-xl font-bold text-[#b3342c]">{formatPct(prediction.confidence)}</div></div></div><div className="mt-4"><div className="mono-label text-[#9d9287]">Dataset-derived indicators</div><div className="mt-2 space-y-2">{prediction.indicators?.map((indicator) => <div key={indicator} className="flex gap-2 text-xs leading-5 text-[#5f5953]"><Check className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[#b3342c]" />{indicator}</div>)}</div></div><div className="mt-5 rounded-xl border border-[#e6dbd2] bg-[#fcfaf7] p-4"><div className="flex items-center gap-2 text-xs font-extrabold"><Lightbulb className="h-4 w-4 text-[#b3342c]" /> Generated explanation</div><p className="mt-2 text-xs leading-5 text-[#6e665f]">{prediction.insight}</p></div></div>;
}

function PredictionsPage() {
  const predictions = useGetPredictions({ query: { queryKey: getGetPredictionsQueryKey() } });
  const [selected, setSelected] = useState<Prediction | null>(null);
  return <div className="rise-in"><PageIntro eyebrow="Traceability" title="Prediction history" description="Every inference remains inspectable: machine context, model identity, confidence, and the evidence attached at creation time." /><Panel eyebrow="Prediction ledger" title={`${predictions.data?.length ?? 0} recorded readings`} action={<button data-testid="button-refresh-predictions" onClick={() => predictions.refetch()} className="rounded-lg p-2 text-[#8b8178] hover:bg-[#f2ece5]"><RefreshCw className="h-4 w-4" /></button>}><QueryState loading={predictions.isLoading} error={predictions.isError} onRetry={() => predictions.refetch()}><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-xs"><thead className="bg-[#faf6f1] text-[10px] uppercase tracking-[.1em] text-[#9d9287]"><tr><th className="px-5 py-3">Created</th><th className="px-3 py-3">Machine</th><th className="px-3 py-3">Health</th><th className="px-3 py-3">Confidence</th><th className="px-3 py-3">Model</th><th className="px-3 py-3" /></tr></thead><tbody className="divide-y divide-[#eee7df]">{predictions.data?.map((item) => <tr key={item.id} className="hover:bg-[#fcf8f4]"><td className="px-5 py-4 text-[#776e66]">{formatDate(item.createdAt)}</td><td className="px-3 py-4 font-extrabold">{item.machineId || 'Unassigned'}</td><td className="px-3 py-4"><StatusBadge value={item.health} /></td><td className="px-3 py-4 font-mono">{formatPct(item.confidence)}</td><td className="px-3 py-4 text-[#776e66]">{item.model}</td><td className="px-3 py-4 text-right"><button data-testid={`button-details-${item.id}`} onClick={() => setSelected(item)} className="font-bold text-[#b3342c]">Details</button></td></tr>)}</tbody></table>{!predictions.data?.length && <EmptyState icon={ClipboardList} title="No predictions recorded" body="Run a manual prediction to create the first traceable inference." action={<Link href="/predict" data-testid="link-history-predict" className="text-xs font-bold text-[#b3342c]">Open inference console</Link>} />}</div></QueryState></Panel>{selected && <div className="fixed inset-0 z-50 grid place-items-center bg-[#1c2028]/45 p-4" onClick={() => setSelected(null)}><div className="w-full max-w-lg rounded-2xl border border-[#e4ddd3] bg-[#fffdfa] shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="flex items-center justify-between border-b border-[#eee7df] p-5"><div><div className="mono-label text-[#a44b42]">Prediction detail</div><h2 className="mt-1 text-lg font-extrabold">{selected.machineId || 'Unassigned reading'}</h2></div><button data-testid="button-close-prediction" onClick={() => setSelected(null)} className="rounded-lg p-2 hover:bg-[#f2ece5]"><X className="h-4 w-4" /></button></div><div className="p-5"><PredictionResult prediction={selected} /><div className="mt-5"><div className="mono-label text-[#9b9188]">Sensor values</div><div className="mt-2 grid grid-cols-2 gap-2">{Object.entries(selected.values).map(([key, value]) => <div key={key} className="rounded-lg bg-[#f8f3ee] p-3"><div className="text-[10px] uppercase text-[#9a9086]">{key}</div><div className="mt-1 font-mono text-sm">{String(value ?? '—')}</div></div>)}</div></div></div></div></div>}</div>;
}

function MachinesPage() {
  const machines = useGetMachines({ query: { queryKey: getGetMachinesQueryKey() } });
  const [filter, setFilter] = useState('all');
  const list = (machines.data ?? []).filter((machine) => filter === 'all' || machine.health.toLowerCase() === filter || machine.risk.toLowerCase() === filter);
  return <div className="rise-in"><PageIntro eyebrow="Fleet register" title="Machines" description="Move from fleet posture to a single machine without losing the reading context." ><div className="flex rounded-xl border border-[#ded4ca] bg-[#fffdfa] p-1">{['all', 'healthy', 'at-risk', 'critical'].map((item) => <button key={item} data-testid={`button-filter-${item}`} onClick={() => setFilter(item)} className={cx('rounded-lg px-3 py-2 text-[11px] font-bold capitalize', filter === item ? 'bg-[#20242c] text-white' : 'text-[#827970] hover:bg-[#f2ece5]')}>{item.replace('-', ' ')}</button>)}</div></PageIntro><Panel eyebrow="Live register" title={`${list.length} visible machines`} action={<button data-testid="button-refresh-machines" onClick={() => machines.refetch()} className="rounded-lg p-2 text-[#8b8178] hover:bg-[#f2ece5]"><RefreshCw className="h-4 w-4" /></button>}><QueryState loading={machines.isLoading} error={machines.isError} onRetry={() => machines.refetch()}><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{list.map((machine) => <Link href={`/machines/${machine.id}`} key={machine.id} data-testid={`card-machine-${machine.id}`} className="group rounded-xl border border-[#e8dfd6] bg-[#fffdfa] p-4 transition-all hover:-translate-y-0.5 hover:border-[#cfaaa0] hover:shadow-md"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f1e9e2] text-[#726960]"><Fan className="h-5 w-5" /></div><div><div className="font-extrabold">{machine.id}</div><div className="mt-0.5 text-[11px] text-[#8d8379]">{machine.type}</div></div></div><ChevronRight className="h-4 w-4 text-[#b9ada2] transition-transform group-hover:translate-x-1" /></div><div className="mt-5 flex items-center justify-between"><StatusBadge value={machine.health} /><span className="text-[11px] text-[#8b8178]">{machine.operatingHours.toLocaleString()} h runtime</span></div><div className="mt-4 flex items-center justify-between border-t border-[#eee7df] pt-3 text-[10px] text-[#9a9087]"><span>Last prediction {formatDate(machine.lastPrediction)}</span><span>{formatDate(machine.lastSeen)}</span></div></Link>)}{!list.length && <div className="col-span-full"><EmptyState icon={ServerCog} title="No machines match" body="Adjust the health filter or profile a dataset to populate the register." /></div>}</div></QueryState></Panel></div>;
}

function MachineDetailPage() {
  const params = useParams<{ machineId: string }>();
  const detail = useGetMachine(params.machineId, { query: { queryKey: getGetMachineQueryKey(params.machineId) } });
  const machine = detail.data;
  const maxTemp = Math.max(...(machine?.sensorTrends?.map((item) => item.temperature) ?? [1]));
  return <div className="rise-in"><Link href="/machines" data-testid="link-back-machines" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-[#8c8178] hover:text-[#b3342c]"><ArrowLeft className="h-4 w-4" /> Back to machines</Link><QueryState loading={detail.isLoading} error={detail.isError} onRetry={() => detail.refetch()}>{machine && <><PageIntro eyebrow={`Machine / ${machine.id}`} title={machine.type} description={machine.insight}><div className="flex items-center gap-2"><StatusBadge value={machine.health} /><StatusBadge value={machine.risk} subtle /></div></PageIntro><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Machine ID" value={machine.id} detail="registered asset" icon={ServerCog} /><Metric label="Operating hours" value={machine.operatingHours.toLocaleString()} detail="lifetime runtime" icon={Clock3} /><Metric label="Predictions" value={machine.predictions.length} detail="machine-specific" icon={Crosshair} tone="red" /><Metric label="Last seen" value={formatDate(machine.lastSeen)} detail="latest telemetry" icon={Activity} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><Panel eyebrow="Telemetry" title="Sensor trends"><div className="p-5"><div className="mb-4 flex flex-wrap gap-3 text-[11px] text-[#7e756d]"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#b3342c]" />Temperature</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#3e8e75]" />Vibration</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#d79a38]" />Pressure</span></div><div className="flex h-48 items-end gap-1 border-b border-l border-[#e5ddd5] px-2 pb-0">{machine.sensorTrends.map((trend, index) => <div key={trend.timestamp} className="group relative flex h-full flex-1 items-end"><div className="w-full rounded-t bg-[#b3342c]/75 transition-all group-hover:bg-[#b3342c]" style={{ height: `${Math.max((trend.temperature / maxTemp) * 88, 8)}%` }} /><span className="absolute bottom-[-24px] left-1/2 hidden -translate-x-1/2 whitespace-nowrap font-mono text-[9px] text-[#968c82] group-hover:block">{index + 1}</span></div>)}</div><div className="mt-8 grid grid-cols-3 gap-2 text-center text-[10px] text-[#978d83]"><span>earlier</span><span>telemetry window</span><span>latest</span></div></div></Panel><Panel eyebrow="Attribution" title="What is driving risk"><div className="p-5">{machine.featureImportance.length ? <div className="space-y-3">{machine.featureImportance.map((item) => <div key={item.feature}><div className="mb-1 flex justify-between text-xs"><span className="font-bold">{item.feature}</span><span className="font-mono text-[#8b8178]">{item.importance.toFixed(3)}</span></div><div className="h-2 rounded-full bg-[#eee8e1]"><div className="h-full rounded-full bg-[#d49537]" style={{ width: `${Math.min(item.importance * 100, 100)}%` }} /></div></div>)}</div> : <EmptyState icon={SlidersHorizontal} title="No attribution available" body="Feature importance will appear when a model has evaluated this machine." />}</div></Panel></div><Panel className="mt-6" eyebrow="History" title="Machine health history"><div className="divide-y divide-[#eee7df]">{machine.predictions.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><div className="text-xs font-extrabold">{formatDate(item.createdAt)}</div><div className="mt-1 text-[11px] text-[#867c73]">{item.model}</div></div><div className="flex items-center gap-4"><StatusBadge value={item.health} /><span className="font-mono text-xs text-[#867c73]">{formatPct(item.confidence)}</span></div></div>)}{!machine.predictions.length && <EmptyState icon={ClipboardList} title="No prediction history" body="This machine has not been evaluated yet." />}</div></Panel></>}</QueryState></div>;
}

function InsightsPage() {
  const sources = useGetRagSources({ query: { queryKey: getGetRagSourcesQueryKey() } });
  const query = useQueryMaintenanceKnowledge();
  const [question, setQuestion] = useState('What should I inspect when vibration rises with temperature?');
  const [answer, setAnswer] = useState<RagResponse | null>(null);
  const ask = () => query.mutate({ data: { query: question, predictionId: null } }, { onSuccess: setAnswer });
  return <div className="rise-in"><PageIntro eyebrow="Knowledge layer" title="Maintenance insights" description="Ask a grounded question and keep retrieved maintenance knowledge distinct from what the model inferred."><div className="mono-label rounded-xl border border-[#d9c7be] bg-[#fffdfa] px-3 py-3 text-[#a64a41]">RAG / source-grounded</div></PageIntro><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Panel eyebrow="Ask maintenance knowledge" title="Explain the next check"><div className="p-5"><div className="rounded-xl border border-[#ded4ca] bg-white p-3 focus-within:border-[#b3342c]"><textarea data-testid="input-maintenance-question" value={question} onChange={(e) => setQuestion(e.target.value)} rows={3} className="w-full resize-none text-sm leading-6 outline-none" /><div className="flex justify-end"><button data-testid="button-ask-maintenance" onClick={ask} disabled={query.isPending || !question.trim()} className="inline-flex items-center gap-2 rounded-lg bg-[#b3342c] px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{query.isPending ? 'Retrieving…' : 'Ask knowledge layer'} <Send className="h-3.5 w-3.5" /></button></div></div>{answer ? <div className="mt-5 rounded-xl bg-[#faf1ed] p-4"><div className="flex items-center gap-2 text-xs font-extrabold"><Sparkles className="h-4 w-4 text-[#b3342c]" /> Generated explanation</div><p className="mt-3 text-sm leading-6 text-[#554e48]">{answer.answer}</p><div className="mt-4 flex flex-wrap gap-1.5">{answer.retrievedTopics.map((topic) => <span key={topic} className="rounded-md bg-white/70 px-2 py-1 font-mono text-[10px] text-[#975048]">{topic}</span>)}</div><div className="mt-5 border-t border-[#e7d8d0] pt-4"><div className="mono-label text-[#9b756e]">Retrieved maintenance knowledge</div><div className="mt-3 space-y-3">{answer.sources.map((source) => <SourceRow key={source.id} source={source} />)}</div></div></div> : <EmptyState icon={Lightbulb} title="No explanation generated" body="The answer will include the retrieved topics and source excerpts used to ground it." />}</div></Panel><Panel eyebrow="Knowledge index" title="Available sources" action={<span className="mono-label text-[#9d9287]">{sources.data?.length ?? 0} indexed</span>}><div className="divide-y divide-[#eee7df]">{sources.data?.map((source) => <SourceRow key={source.id} source={source} />)}{!sources.data?.length && <EmptyState icon={BookOpen} title="No sources indexed" body="Maintenance references will appear when the knowledge index is available." />}</div></Panel></div></div>;
}

function SourceRow({ source }: { source: RagSource }) {
  return <div className="p-4"><div className="flex gap-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#f1e7e0] text-[#b3342c]"><BookOpen className="h-4 w-4" /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><div className="text-xs font-extrabold">{source.title}</div><span className="mono-label text-[#a69b91]">{source.category}</span></div><p className="mt-2 text-[11px] leading-5 text-[#776e66]">{source.excerpt}</p></div></div></div>;
}

function ModelsPage() {
  const results = useGetModelResults({ query: { queryKey: getGetModelResultsQueryKey() } });
  const analysis = useGetAnalysisSummary();
  const training: TrainingResults | undefined = results.data;
  const models: ModelResult[] = training?.models ?? analysis.data?.modelResults ?? [];
  return <div className="rise-in"><PageIntro eyebrow="Model governance" title="Model registry" description="Make the selected model legible: compare metrics, understand its note, and see which version is active for inference." /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><Panel eyebrow="Active selection" title="Production model"><div className="p-5">{training ? <div className="rounded-xl bg-[#20242c] p-5 text-white"><div className="mono-label text-white/45">Selected model</div><div className="mt-2 text-2xl font-extrabold tracking-[-.04em]">{training.selectedModel}</div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-lg bg-white/8 p-3"><div className="mono-label text-white/40">Target</div><div className="mt-1 text-xs font-bold">{training.targetColumn}</div></div><div className="rounded-lg bg-white/8 p-3"><div className="mono-label text-white/40">Trained</div><div className="mt-1 text-xs font-bold">{formatDate(training.trainedAt)}</div></div></div></div> : <EmptyState icon={BrainCircuit} title="No active model" body="Train and compare models from the analysis page to select the inference model." action={<Link href="/analysis" data-testid="link-models-analysis" className="text-xs font-bold text-[#b3342c]">Open analysis</Link>} />}</div></Panel><Panel eyebrow="Benchmark" title="Transparent comparison"><div className="overflow-x-auto"><table className="w-full min-w-[630px] text-left text-xs"><thead className="bg-[#faf6f1] text-[10px] uppercase tracking-[.1em] text-[#9d9287]"><tr><th className="px-5 py-3">Model</th><th className="px-3 py-3">Accuracy</th><th className="px-3 py-3">Precision</th><th className="px-3 py-3">Recall</th><th className="px-3 py-3">F1</th></tr></thead><tbody className="divide-y divide-[#eee7df]">{models.map((model) => <tr key={model.name} className={cx(model.selected && 'bg-[#fff4f0]')}><td className="px-5 py-4"><div className="flex items-center gap-2 font-extrabold">{model.name}{model.selected && <CircleCheck className="h-3.5 w-3.5 text-[#b3342c]" />}</div><div className="mt-1 text-[10px] text-[#8e847a]">{model.note}</div></td><td className="px-3 py-4 font-mono">{formatPct(model.accuracy)}</td><td className="px-3 py-4 font-mono">{formatPct(model.precision)}</td><td className="px-3 py-4 font-mono">{formatPct(model.recall)}</td><td className="px-3 py-4 font-mono font-bold">{formatPct(model.f1)}</td></tr>)}</tbody></table>{!models.length && <EmptyState icon={BrainCircuit} title="Comparison is empty" body="No training results have been published yet." />}</div></Panel></div><div className="mt-6 rounded-2xl border border-[#e4ddd3] bg-[#fffdfa] p-5"><div className="flex items-start gap-3"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[#b3342c]" /><div><div className="text-xs font-extrabold">Why this matters</div><p className="mt-1 max-w-3xl text-xs leading-5 text-[#756c64]">Model selection is evidence-led rather than hidden behind a single score. The active choice is carried into every prediction, while the benchmark remains available for review.</p></div></div></div></div>;
}

function AppRouter() {
  return <Switch><Route path="/" component={Overview} /><Route path="/dashboard" component={Overview} /><Route path="/dataset" component={DatasetPage} /><Route path="/analysis" component={AnalysisPage} /><Route path="/predict" component={PredictPage} /><Route path="/predictions" component={PredictionsPage} /><Route path="/machines" component={MachinesPage} /><Route path="/machines/:machineId" component={MachineDetailPage} /><Route path="/insights" component={InsightsPage} /><Route path="/models" component={ModelsPage} /><Route component={NotFound} /></Switch>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><Shell><AppRouter /></Shell></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;